local config = {
  ui_story_30860401_1_dialog_content = "Jadi, kamu bilang, kamu menemukan beberapa <color=#FFB400>bunga putih</color> di Colossus?",
  ui_story_30860401_2_dialog_content = "Bunga putihmu, persisnya.",
  ui_story_30860401_3_dialog_content = "Beberapa hari terakhir, aku selalu bangun pagi-pagi untuk berlatih...",
  ui_story_30860401_4_dialog_content = "Dan aku mulai mencium bau tidak biasa yang seperti bunga.",
  ui_story_30860401_5_dialog_content = "Akhirnya, baru pagi ini, aku menemukan asal bau itu.",
  ui_story_30860401_6_dialog_content = "Seseorang telah menanam bunga putih misterius ini di semua sudut Colossus...",
  ui_story_30860401_7_dialog_content = "Tapi ada banyak orang di sini yang punya bunga.",
  ui_story_30860401_8_dialog_content = "Betul, ada banyak orang yang punya bunga di Colossus...",
  ui_story_30860401_X8_dialog_content = "Hiiro, Nikinis, Jola...",
  ui_story_30860401_9_dialog_content = "Tapi cuma kau yang punya bunga putih semacam ini!",
  ui_story_30860401_10_dialog_content = "Kamu yakin sekali aku pelakunya, ya... Apa yang membuatmu seyakin itu?",
  ui_story_30860401_11_dialog_content = "Aku punya bukti!",
  ui_story_30860401_17_dialog_content = "Apa ini ide leluconmu? Pertama, kau menaruh bunga di kepala Lord, lalu kamu menanamnya di seluruh Colossus?",
  ui_story_30860401_18_dialog_content = "Tidak!",
  ui_story_30860401_19_dialog_content = "Tentu saja tidak ♩",
  ui_story_30860401_20_dialog_content = "Orang yang menanam bunga itu♫ ♩",
  ui_story_30860401_21_dialog_content = "Sering menundukkan kepala dan <color=#FFB400>berdoa</color>.",
  ui_story_30860401_22_dialog_content = "Dan mengucapkan <color=#FFB400>belasungkawa</color>!",
  ui_story_30860401_23_dialog_content = "(Berdoa? Belasungkawa? Kok terdengar seperti seorang <color=#FFB400>pengurus pemakaman</color>?!)",
  ui_story_30860401_24_dialog_content = "Berarti <color=#FFB400>Uriah</color>!",
  ui_story_30860401_25_dialog_content = "Kamu tidak bisa membodohiku!",
  ui_story_30860401_26_dialog_content = "Aku sudah melakukan riset, dan bunga putih ini sama persis dengan bunga-bunga rambatmu!",
  ui_story_30860401_27_dialog_content = "Jadi, kau menyalahkanku atas masalah ini?",
  ui_story_30860401_28_option_content = "Bukan itu maksudku!",
  ui_story_30860401_29_dialog_content = "Aku hanya ingin bertanya tentang itu...",
  ui_story_30860401_30_option_content = "Kamu tidak akan dihukum karena kejahatan atau apa pun...",
  ui_story_30860401_31_dialog_content = "Aku hanya penasaran saja.",
  ui_story_30860401_32_dialog_content = "Semua bunga yang tersebar di Colossus...",
  ui_story_30860401_33_dialog_content = "Aku baru pertama kali melihat orang menanam bunga di Colossus.",
  ui_story_30860401_34_dialog_content = "Karena kamu yakin sekali akulah orangnya, izinkan aku untuk meminta maaf.",
  ui_story_30860401_35_dialog_content = "Walau ini sungguh-sungguh bukan hal yang harus terus dirahasiakan.",
  ui_story_30860401_36_dialog_content = "Jadi, kamulah yang menanam bunga ini, 'kan?",
  ui_story_30860401_37_dialog_content = "Itu hanya bagian kecil dari doa-doaku. Kamu tidak terganggu, 'kan?",
  ui_story_30860401_38_option_content = "Tentu saja tidak...",
  ui_story_30860401_39_dialog_content = "Malah, aku senang melihat begitu banyak bunga setelah berlatih sepanjang hari.",
  ui_story_30860401_40_option_content = "Aku cuma khawatir itu akan merusak Soroz...",
  ui_story_30860401_41_dialog_content = "Tenanglah, bunga ini tidak tumbuh secara alami—bahkan batangnya terbuat dari bunga rambatku.",
  ui_story_30860401_42_dialog_content = "Aku menyebarkannya di Colossus sebagai tanda penghormatan.",
  ui_story_30860401_43_dialog_content = "Mumpung kamu menyebutnya, bunga putih itu juga ada di bunga rambatmu. Apa bunga itu favoritmu?",
  ui_story_30860401_44_dialog_content = "Bukannya bunga itu favoritku, tapi...",
  ui_story_30860401_45_dialog_content = "Kamu tahu arti bunga-bunga ini?",
  ui_story_30860401_46_option_content = "Hmmm, tidak...",
  ui_story_30860401_47_dialog_content = "Apa artinya?",
  ui_story_30860401_48_option_content = "Kurang lebih, ya...",
  ui_story_30860401_49_dialog_content = "Jadi, artinya berkaitan dengan kekuatanmu?",
  ui_story_30860401_50_dialog_content = "Bunga ini melambangkan \"<color=#FFB400>perpisahan yang tragis</color>\".",
  ui_story_30860401_51_dialog_content = "Jadi... kekuatanmu berkaitan dengan perpisahan?",
  ui_story_30860401_52_dialog_content = "Berkaitan dengan keluargamu?",
  ui_story_30860401_53_dialog_content = "Ya... dan denganku juga.",
  ui_story_30860401_54_dialog_content = "Kau sangat pengertian, mau mendengarkanku selama ini. Aku akan mendoakanmu siang dan malam.",
  ui_story_30860401_55_dialog_content = "Aku terkadang tidak tahu apakah kamu serius atau tidak.",
  ui_story_30860401_56_dialog_content = "Ehem, omong-omong... Sebagai Navigator, tugasku adalah memahami kru sebaik mungkin, 'kan?",
  ui_story_30860401_57_dialog_content = "Kalau kamu sungguh ingin tahu, aku akan dengan senang hati bercerita tentang masa laluku.",
  ui_story_30860401_58_dialog_content = "Tapi sebagai gantinya, kamu mau bercerita tentang hal-hal yang membuatmu berkabung?",
  ui_story_30860401_59_dialog_content = "Aku? Apa hubungannya ini denganku?",
  ui_story_30860401_60_dialog_content = "Keluargamu, misalnya. Hal-hal yang ingin kau lindungi... Hal-hal yang harus kamu tinggalkan...",
  ui_story_30860401_61_dialog_content = "Itu semua masa lalu yang sudah jauh sekali... Lagi pula, aku tidak ingat banyak tentang keluargaku.",
  ui_story_30860401_62_dialog_content = "Apa pun boleh. Bagaimana?",
  ui_story_30860401_63_dialog_content = "Hmm... Aku yakin kamu sudah dengar bahwa aku dibesarkan oleh Soroz selama hidupku, 'kan?",
  ui_story_30860401_64_dialog_content = "Ah, ya, White Colossus yang mengagumkan itu.",
  ui_story_30860401_65_dialog_content = "Selama 17 tahun, aku tumbuh di sini. Awalnya, aku tidak memahami apa pun tentang dunia luar.",
  ui_story_30860401_66_dialog_content = "Sebagian besar bayangan di kepalaku adalah kepingan memori yang kudapatkan dari Soroz...",
  ui_story_30860401_67_dialog_content = "Seperti bagaimana aku disembunyikan di Colossus ini...",
  ui_story_30860401_68_dialog_content = "Dan bagaimana bangsaku tewas saat melawan Eclipsite... untuk melindungiku.",
  ui_story_30860401_69_dialog_content = "Tapi lagi-lagi, semua memori ini tertanam di otakku. Aku tidak mungkin mengonfirmasi apakah itu nyata atau tidak...",
  ui_story_30860401_70_dialog_content = "Aku juga sudah mengetahui hal ini.",
  ui_story_30860401_71_dialog_content = "Serta sesuatu yang kamu tidak tahu.",
  ui_story_30860401_72_dialog_content = "Sesuatu... yang aku tidak tahu?",
  ui_story_30860401_73_dialog_content = "Kamu ingat <color=#FFB400>tanda merah di sayap Colossus</color>?",
  ui_story_30860401_74_option_content = "Ya, aku ingat...",
  ui_story_30860401_75_dialog_content = "Suatu kali ketika aku membersihkan Colossus, Vice mengomeliku karena Soroz tampak begitu jorok. Itu membuatnya sangat marah selama beberapa waktu.",
  ui_story_30860401_76_option_content = "Aku tidak ingat...",
  ui_story_30860401_77_dialog_content = "Tapi dulu, ada tanda di Colossus yang tidak bisa aku bersihkan betapa pun kerasnya aku mencoba.",
  ui_story_30860401_78_dialog_content = "Tanda-tanda itu memiliki cerita, bukan hanya kotoran di mesin.",
  ui_story_30860401_79_dialog_content = "Jadi, apa itu?",
  ui_story_30860401_80_dialog_content = "Di semua kepingan memori itu... kamu yakin belum pernah melihatnya?",
  ui_story_30860401_81_dialog_content = "Tunggu, mungkinkah...",
  ui_story_30860401_82_dialog_content = "Betul sekali. Itu bukan noda biasa, tapi <color=#FFB400>darah</color> rekanmu sesama Caelestite.",
  ui_story_30860401_83_dialog_content = "Soroz tidak pernah melupakannya. Itu simbol sejarahnya denganmu saat kamu tumbuh besar.",
  ui_story_30860401_84_dialog_content = "Bagaimana kamu bisa tahu tentang ini, Uriah?",
  ui_story_30860401_85_dialog_content = "Saat pertama kali datang ke Colossus, aku menemukan sebuah <color=#FFB400>catatan harian</color>...",
  ui_story_30860401_86_dialog_content = "Kemungkinan besar, pemiliknya sudah tiada... Halaman-halamannya penuh cerita tentangmu dan bangsamu.",
  ui_story_30860401_87_dialog_content = "Aku minta maaf karena tidak seharusnya aku membaca catatan itu.",
  ui_story_30860401_88_dialog_content = "Aku tidak tahu apa-apa saat menemukannya, dan aku sudah menunggu kesempatan untuk memberikannya kepadamu.",
  ui_story_30860401_89_dialog_content = "Aku berdoa untuk momen ini sejak lama...",
  ui_story_30860401_90_dialog_content = "Dan sekarang, kurasa ini waktu yang tepat untuk mengembalikannya kepadamu.",
  ui_story_30860401_91_dialog_content = "Catatan harian ini, dan bunga-bunga ini... Mohon terimalah.",
  ui_story_30860401_92_dialog_content = "Kuharap kamu bisa berkabung dan berdoa untuk bangsamu yang gugur, dan memberi mereka perpisahan yang pantas.",
  ui_story_30860401_93_dialog_content = "*Mengambil bunga putih*",
  ui_story_30860401_94_dialog_content = "Menurut catatan harian, hari ini adalah hari berkabung untuk mereka yang sudah tiada...",
  ui_story_30860401_95_dialog_content = "Perpisahan yang pantas, ya... Ini pertama kalinya aku mendengar hari raya seperti itu.",
  ui_story_30860401_96_dialog_content = "Aku harus melakukan sesuatu yang istimewa untuk memperingati mereka... Terima kasih.",
  ui_story_30860401_97_dialog_content = "Seperti orang lain, aku juga akan mendoakanmu.",
  ui_story_30860401_98_dialog_content = "Hmm... Kenapa aku merasa seperti melupakan sesuatu?",
  ui_story_30860401_99_dialog_content = "Apa kamu yang melupakan sesuatu?",
  ui_story_30860401_100_dialog_content = "Aku... tidak?",
  ui_story_30860401_101_dialog_content = "Sepertinya iya. Kau sebaiknya beristirahat. Aku akan berdoa untukmu malam ini sebelum tidur.",
  ui_story_30860401_X101_dialog_content = "Sampai bertemu.",
  ui_story_30860401_102_dialog_content = "Tunggu, aku ingat sekarang! Kamu seharusnya bercerita tentang masa lalumu...",
  ui_story_30860401_103_dialog_content = "Ke mana dia pergi?!",
  ui_story_30860401_104_dialog_content = "Uriah!!",
  ui_story_30860601_1_dialog_content = "Kamu bisa dengar <color=#FFB400>suara</color> itu?",
  ui_story_30860601_2_dialog_content = "Suara?",
  ui_story_30860601_3_dialog_content = "Ombak bergulung di pantai, burung camar berkaok sambil bermain.",
  ui_story_30860601_4_dialog_content = "Daun pohon palem panjang bergoyang ditiup angin, dan suara langkah kaki di atas pasir.",
  ui_story_30860601_5_dialog_content = "Semua suara ini sungguh penuh semangat musim panas! Ah, sungguh menenangkan...",
  ui_story_30860601_6_dialog_content = "Dengarkan baik-baik.",
  ui_story_30860601_7_dialog_content = "Wow, kamu benar! Saat kuperhatikan, ada banyak sekali suara di sekitar kita!",
  ui_story_30860601_8_dialog_content = "Iya.",
  ui_story_30860601_9_dialog_content = "(Tidak setiap hari raut wajah Uriah tampak seperti ini.)",
  ui_story_30860601_10_dialog_content = "(Biasanya, dia tampak sangat berkarisma dan anggun, dan seluruh tubuhnya tertutup dari kepala sampai kaki... seperti patung, atau semacam itulah.)",
  ui_story_30860601_11_dialog_content = "(Tapi, sepertinya raut wajahnya yang serius itu pun akhirnya luntur juga di pantai ini.)",
  ui_story_30860601_12_dialog_content = "Aku tahu apa yang kaupikirkan, bahwa kau jarang melihatku seperti ini.",
  ui_story_30860601_13_dialog_content = "Tapi, pakaian itu pas sekali untuk menangkal hawa gerah musim panas.",
  ui_story_30860601_14_dialog_content = "Menurutmu, pakaian ini cocok untukku?",
  ui_story_30860601_15_option_content = "Sangat cocok!",
  ui_story_30860601_16_dialog_content = "Walau memang dirancang untuk berenang, pakaianmu itu masih menyiratkan gaya dan kualitas Lumopolis yang anggun.",
  ui_story_30860601_17_dialog_content = "Saat mengenakannya, kamu tampak mulia dan murni di mata semua orang! Seperti mutiara dari laut!",
  ui_story_30860601_18_dialog_content = "Aku... tak yakin apakah omonganku masuk akal atau tidak.",
  ui_story_30860601_19_dialog_content = "Aku tak pernah menyangka akan menerima pujian setulus itu darimu. Terima kasih.",
  ui_story_30860601_20_dialog_content = "Jujur saja, saat tadi kita tiba di pantai, kukira kamu akan tetap mengenakan pakaian biarawati seperti biasanya.",
  ui_story_30860601_21_option_content = "Cukup mengejutkan.",
  ui_story_30860601_22_dialog_content = "Pakaian ini cukup berbeda dari yang biasanya kaukenakan.",
  ui_story_30860601_23_dialog_content = "Dalam bayanganku, kamu selalu mengenakan pakaian biarawati.",
  ui_story_30860601_24_dialog_content = "Aku harus berpakaian pantas saat berdoa.",
  ui_story_30860601_25_dialog_content = "Aku merawat pakaianku dengan cermat, sama seperti merawat bunga-bunga putihku.",
  ui_story_30860601_26_dialog_content = "Ini adalah tanda penghormatan bagi orang-orang yang terluka, yang sudah tiada, dan orang-orang terkasih yang mereka tinggalkan.",
  ui_story_30860601_27_dialog_content = "Kurasa tak seorang pun akan mau dipimpin oleh orang yang berpakaian asal-asalan saat menjalani kerasnya hidup. Iya, 'kan?",
  ui_story_30860601_28_dialog_content = "Tapi, saat ini aku sedang tidak bertugas.",
  ui_story_30860601_29_dialog_content = "Kenapa kamu memutuskan datang ke Ocean Sovereign?",
  ui_story_30860601_30_dialog_content = "Aku datang karena diundang oleh Kapten Carleen.",
  ui_story_30860601_31_dialog_content = "Dia gadis yang baik dan penuh perhatian. Dia khawatir aku bekerja terlalu keras, dan ingin aku lebih banyak meluangkan waktu untuk diriku sendiri.",
  ui_story_30860601_32_dialog_content = "Mana mungkin aku bisa menolak undangan yang begitu baik dan penuh perhatian ini.",
  ui_story_30860601_33_dialog_content = "Lagi pula... aku sudah cukup lama mengenal Ocean Sovereign, dan sudah lama aku ingin melihatnya langsung.",
  ui_story_30860601_34_dialog_content = "Aku yakin mungkin aku juga bisa menemukan <color=#FFB400>suara yang kucari-cari</color>.",
  ui_story_30860601_35_dialog_content = "Apa kamu tahu cerita tentang Ocean Sovereign, PlayerName?",
  ui_story_30860601_36_dialog_content = "Bonacie pernah menceritakannya kepadaku. Ocean Sovereign adalah upacara yang ditinggalkan oleh kaum Aurorian yang dulu tinggal di pantai ini.",
  ui_story_30860601_37_dialog_content = "Upacara itu adalah kompetisi untuk menguji <color=#FFB400>kekuatan</color>, <color=#FFB400>pengetahuan</color>, dan <color=#FFB400>keberanian</color> para peserta untuk mencari pemenangnya.",
  ui_story_30860601_38_dialog_content = "Festival itu diharapkan akan membawa cuaca bagus untuk tempat ini.",
  ui_story_30860601_39_dialog_content = "Kamu benar sekali, tapi kok kamu bisa tahu bahwa Ocean Sovereign ditujukan untuk menguji ketiga hal itu?",
  ui_story_30860601_40_dialog_content = "Hah? Memangnya ada cerita di baliknya?",
  ui_story_30860601_41_dialog_content = "\"Suara-suara itu membawa kisah dari masa lalu.\"",
  ui_story_30860601_42_dialog_content = "Dahulu kala, orang-orang yang tinggal di pesisir pantai ini hidup dengan mengandalkan karunia dari langit dan laut.",
  ui_story_30860601_43_dialog_content = "Lama-kelamaan, mereka mulai menyepelekan karunia itu.",
  ui_story_30860601_44_dialog_content = "Lalu, suatu hari, langit tak lagi mencurahkan hujan, laut surut, dan segala yang hidup di air pun mati.",
  ui_story_30860601_45_dialog_content = "Di kejauhan, sebuah kastel muncul dari dalamnya laut, dan awan gelap menyelubungi seluruh Celestial Coast.",
  ui_story_30860601_46_dialog_content = "Kondisi pantai ini hanya bisa dipulihkan dengan menuntaskan ujian dari ketiga dewi, yaitu Dewi Kekuatan, Pengetahuan, dan Keberanian.",
  ui_story_30860601_47_dialog_content = "Biasanya, akan muncul seorang pahlawan yang menyelamatkan semuanya!",
  ui_story_30860601_48_dialog_content = "Tepat sekali.",
  ui_story_30860601_49_dialog_content = "Untuk menyelamatkan wilayah pesisir ini, seorang <color=#FFB400>raja</color> saat itu maju untuk mengikuti ujian tersebut.",
  ui_story_30860601_50_dialog_content = "Dengan kekuatannya yang tak tertandingi, dia menutup kastel itu.",
  ui_story_30860601_51_dialog_content = "Dengan pikirannya yang cerdas, dia berhasil mengungguli Dewi Pengetahuan dalam permainan ciptaan sang dewi itu sendiri.",
  ui_story_30860601_52_dialog_content = "Dan terakhir, dengan keberaniannya yang luar biasa, dia berhasil mengatasi ketakutan terbesarnya dan lolos dari ujian Dewi Keberanian.",
  ui_story_30860601_53_dialog_content = "Akhirnya, sang raja mendapatkan restu dari ketiga dewi itu.",
  ui_story_30860601_54_dialog_content = "Setelah menerima restu dari mereka, hujan pun kembali tercurah dari langit, dan air laut kembali naik ke pantai dan membawa serta ragam kehidupan laut.",
  ui_story_30860601_55_dialog_content = "Para dewi itu menggunakan kekuatan mereka untuk mengembalikan sang raja ke kerajaannya sendiri.",
  ui_story_30860601_56_dialog_content = "Tapi, dunia ini selalu berubah, dan saat dia kembali ke kerajaannya, semuanya sudah tak lagi seperti dulu.",
  ui_story_30860601_57_dialog_content = "Ratusan tahun sudah berlalu, dan keluarga maupun teman-temannya sudah lama tiada.",
  ui_story_30860601_58_dialog_content = "Karena berduka, sang raja pun mengubah dirinya menjadi sebongkah batu di atas tebing. Dari sana, dia selalu melindungi masa depan kerajaannya.",
  ui_story_30860601_59_dialog_content = "Walaupun orang-orang terkasihnya sudah tak lagi bersamanya, kisah tentang keberaniannya tak lekang oleh waktu. Untuk menghormati sang raja dan ketiga dewi itu, muncullah Ocean Sovereign.",
  ui_story_30860601_60_dialog_content = "Bagi warga sekitar sini, kekuatan, pengetahuan, dan keberanian adalah tiga hal yang harus dimiliki setiap orang.",
  ui_story_30860601_61_dialog_content = "Kedengarannya seperti dongeng.",
  ui_story_30860601_62_dialog_content = "Maksudmu, kamu menganggap kisah ini tak nyata?",
  ui_story_30860601_X62_dialog_content = "Mungkin agak tak nyata...",
  ui_story_30860601_63_dialog_content = "Walau kisahnya terdengar seperti dibuat-buat, Ocean Sovereign memang ada.",
  ui_story_30860601_64_dialog_content = "Begitu pula ujian untuk menilai kekuatan, pengetahuan, dan keberanian.",
  ui_story_30860601_65_dialog_content = "(Walau sebenarnya \"ujian\" itu hanya berupa lomba voli, catur, dan menyanyi...)",
  ui_story_30860601_66_dialog_content = "Apa pendapatmu tentang kisah ini, Uriah?",
  ui_story_30860601_67_dialog_content = "Apa pendapatku? Yah...",
  ui_story_30860601_68_dialog_content = "Ayo, tak ada yang istimewa di sini.",
  ui_story_30860601_69_dialog_content = "Ada ribut-ribut apa di sana?",
  ui_story_30860601_70_dialog_content = "Sudah kubilang 'kan, acara ini sebenarnya hanya bertujuan untuk menguras uang para wisatawan yang berkunjung kemari.",
  ui_story_30860601_71_dialog_content = "Mereka membesar-besarkan suatu kisah, lalu mengadakan berbagai acara tak jelas untuk mendongkrak bisnis.",
  ui_story_30860601_72_dialog_content = "Setelah itu, mereka mendirikan kios di mana-mana untuk mengeruk keuntungan. Es serut, minuman dingin, pakaian renang, produk bertema pantai...",
  ui_story_30860601_73_dialog_content = "Pada akhirnya, inti dari semua ini hanyalah untuk menguras uang kita.",
  ui_story_30860601_74_dialog_content = "Maksudku, mana ada orang yang benar-benar percaya pada kisah \"Ocean Sovereign\" yang konyol ini, 'kan? Atau omong kosong tentang kekuatan, keberanian, dan pengetahuan itu...",
  ui_story_30860601_75_dialog_content = "(Mau tak mau aku harus mengakui bahwa dia memang benar...)",
  ui_story_30860601_76_dialog_content = "Cukup sudah.",
  ui_story_30860601_77_dialog_content = "...",
  ui_story_30860601_78_dialog_content = "Kamu baik-baik saja, Uriah?",
  ui_story_30860601_79_dialog_content = "Ya. Yang dikatakannya memang benar.",
  ui_story_30860601_80_dialog_content = "Apa pun yang kita katakan atau pikirkan, legenda seperti ini pada akhirnya akan sirna, dan yang tersisa hanyalah hal-hal yang mirip dengan kisah aslinya.",
  ui_story_30860601_81_dialog_content = "Ocean Sovereign, si raja batu, kastel di laut—semua itu hanya ada dalam khayalan orang-orang, dan lama-kelamaan akan berubah dan memudar.",
  ui_story_30860601_82_dialog_content = "Sayang sekali... Ini jelas bukan suara yang ingin kudengar.",
  ui_story_30860601_83_dialog_content = "Uriah!",
  ui_story_30860601_84_dialog_content = "Ya?",
  ui_story_30860601_85_dialog_content = "Aku... aku mau percaya pada kisah itu!",
  ui_story_30860601_86_dialog_content = "PlayerName?",
  ui_story_30860601_87_dialog_content = "Karena... <size=45>menurutku, kisah itu sangat romantis!</size>",
  ui_story_30860601_88_dialog_content = "Untuk melindungi negerinya, sang raja itu menempuh sekian banyak kesulitan... Dia membuktikan bahwa kekuatan, pengetahuan, dan keberaniannya memang nyata!",
  ui_story_30860601_89_dialog_content = "Dan walaupun ujian yang dilaluinya itu mengubah hidupnya, dia sama sekali tak menyesalinya, dan bahkan mengubah dirinya menjadi batu agar bisa terus melindungi wilayah pesisir ini...",
  ui_story_30860601_90_dialog_content = "Kalau Ocean Sovereign berasal dari kisah seperti ini, PASTI ada maknanya!",
  ui_story_30860601_91_dialog_content = "Hmm... Rupanya seperti itulah pandanganmu, PlayerName.",
  ui_story_30860601_92_dialog_content = "(Sepertinya Uriah sedang berpikir keras. Apa tadi aku mengatakan hal yang tidak pantas?)",
  ui_story_30860601_93_dialog_content = "Jangan gugup begitu, PlayerName. Suaramu saat mengutarakan pendapatmu terdengar kuat dan meyakinkan.",
  ui_story_30860601_94_dialog_content = "Lagi pula, menurutku, penafsiranmu tentang kisah ini juga sangat mantap. Memang seperti inilah suara yang ingin kudengar.",
  ui_story_30860601_95_dialog_content = "Apa kamu tahu bahwa kerang juga bisa menyimpan suara?",
  ui_story_30860601_96_dialog_content = "Kerang akan menyimpan gema indah di dalam liku-liku spiralnya. Saat kita mengajukan pertanyaan kepadanya, dia akan langsung menjawab.",
  ui_story_30860601_97_dialog_content = "Aku ingin menyimpan suaramu, jadi tolong... ucapkan kata-kata yang tadi kausampaikan kepadaku ke dalam kerang ini!",
  ui_story_30860601_98_dialog_content = "Ke dalam kerang ini...?",
  ui_story_30860601_99_dialog_content = "(Kenapa semua orang memandangiku?! Tiba-tiba saja aku jadi merasa canggung...)",
  ui_story_30860601_100_dialog_content = "(Tapi, jika ini untuk Uriah... akan kulakukan!!!)",
  ui_story_30860601_101_dialog_content = "<size=45>Menurutku, kisah tentang Ocean Sovereign ini sangat romantis!</size>",
  ui_story_30860601_102_dialog_content = "Huh, tak kusangka ternyata ada orang yang begitu polos di dunia ini.",
  ui_story_30860601_103_dialog_content = "Ayo, kita pergi...",
  ui_story_30860601_104_dialog_content = "Yah, ayo...",
  ui_story_30860601_105_dialog_content = "(Tapi, aku juga merasa bahwa kisah Ocean Sovereign ini memang sangat romantis...)",
  ui_story_30860601_106_dialog_content = "Terima kasih, PlayerName.",
  ui_story_30860601_107_dialog_content = "Aku pun kaget melihat sisi dirimu yang seperti ini. Kaget, tapi senang.",
  ui_story_30860601_108_dialog_content = "Jujur saja, aku tahu kisah ini tak sepenuhnya benar.",
  ui_story_30860601_109_dialog_content = "Tapi, hampir setiap hari aku menghadapi rasa sakit dan penderitaan nyata, jadi aku pun belajar untuk menghargai kebahagiaan kecil yang bisa dihadirkan oleh dongeng karangan seperti ini.",
  ui_story_30860601_110_dialog_content = "Yah, kalau kamu senang, aku juga ikut senang!",
  ui_story_30860601_111_dialog_content = "Mana mungkin aku tak senang kalau kamu ada di sini?",
  ui_story_30860601_112_dialog_content = "Makna sesungguhnya dari hari libur dan festival terletak pada pesan yang ingin disampaikan secara turun-temurun.",
  ui_story_30860601_113_dialog_content = "Bagi kami, nilainya terletak pada <color=#FFB400>apa yang kami yakini</color>.",
  ui_story_30860601_114_dialog_content = "Aku sudah menemukan keyakinan dalam sesuatu yang layak dipercayai.",
  ui_story_30860601_115_dialog_content = "Dan \"sesuatu\" itu adalah pilihan kita untuk percaya pada <color=#FFB400>sifat-sifat baik dan jujur tersebut</color>.",
  ui_story_30860601_116_dialog_content = "Kekuatan, pengetahuan, dan keberanian.",
  ui_story_30860601_117_dialog_content = "Kesimpulannya, aku yakin bahwa sedikit romantisme bisa membuat hidup kita lebih panjang dan lebih bahagia.",
  ui_story_30860601_118_dialog_content = "Aku juga yakin bahwa orang sepertimu pasti akan hidup bahagia, apa pun kesulitan yang mungkin akan kauhadapi dalam hidupmu.",
  ui_story_30860601_119_dialog_content = "Kita sudahi dulu acara berjalan-jalan di sini untuk hari ini. Kita harus pulang dan istirahat.",
  ui_story_30860601_120_dialog_content = "Iya! Kalau begitu, ayo pulang.",
  ui_story_30860601_121_dialog_content = "Oh, satu hal lagi.",
  ui_story_30860601_122_dialog_content = "<color=#e8d9bb>Uriah mengambil kerang dan membisikkan sesuatu ke dalamnya.</color>",
  ui_story_30860601_123_dialog_content = "Uriah?",
  ui_story_30860601_124_dialog_content = "Aku hanya merekam apa yang paling ingin kusampaikan.",
  ui_story_30860601_125_dialog_content = "Tapi, ini rahasia. Suatu hari nanti, mungkin kamu bisa mendengarnya dari dalam kerang ini.",
  ui_story_30860601_126_dialog_content = "\"Terima kasih, PlayerName. Inilah suara yang paling ingin kudengar hari ini.\""
}
return config
